-- DOMAIN-MANAGERS-1 (2026-11-04, charter pillar autonomy; cost pillar): product, cost, social and outreach managers.
-- Deterministic SQL only, zero AI calls. Hourly :45 workflow reads live ledgers (v_cost_run_rate, v_channel_impact_7d, outreach_log, product_registry),
-- writes one persona_briefs row per manager (fleet.qnfo.org/managers) and files at most one deduped issue per breach with a lever and a closing condition.
-- Outreach manager only reports: it never sends and never touches consent, suppression or opt-out. Ceiling: ops_config cost_manager_monthly_usd (default 100).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261104_domain_managers
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name = 'domain-managers-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'domain-managers'; UPDATE metric_registry SET state = 'RETIRED' WHERE metric = 'domain_manager_briefs'; UPDATE management_personas SET status = 'retired' WHERE persona_key LIKE 'product:%' OR persona_key IN ('manager:cost','manager:social','manager:outreach');

CREATE TABLE IF NOT EXISTS bak_20261104_domain_managers AS SELECT persona_key, status FROM management_personas;

INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('cost_manager_monthly_usd', '100', 'DOMAIN-MANAGERS-1 monthly run-rate ceiling in USD', datetime('now'));

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('domain-managers', 'DOMAIN-MANAGERS-1: product, cost, social and outreach managers (SQL only)', 'workflow', '{"steps": [{"type": "sql", "name": "personas", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, decision_authority, sla_min, path_a, status, updated_at) VALUES (''manager:cost'',''function'',''cost'',''Keep AI and platform spend falling; name the biggest source every hour.'',''files one COST-MANAGER-1 issue per breach of ops_config cost_manager_monthly_usd'',60,''fleet_tasks domain-managers'',  ''active'', datetime(''now'')),(''manager:social'',''function'',''social'',''Hold every social channel at its weekly cadence and show clicks per post.'',''files one SOCIAL-MANAGER-1 issue per channel under half its weekly target'',60,''fleet_tasks domain-managers'',''active'', datetime(''now'')),(''manager:outreach'',''function'',''outreach'',''Keep e-mail outreach flowing inside consent and opt-out; never sends, never changes suppression.'',''reports only; files OUTREACH-MANAGER-1 when nothing was sent for 7 days'',60,''fleet_tasks domain-managers'',''active'', datetime(''now''))"}, {"type": "sql", "name": "product-personas", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, decision_authority, sla_min, path_a, status, updated_at) SELECT ''product:'' || product, ''product'', product, ''Own '' || product || '' ('' || COALESCE(host,'''') || ''): '' || COALESCE(what_for,''''), ''plussing cadence is set by product_registry; this manager reports its state hourly'', 60, ''fleet_tasks domain-managers'', ''active'', datetime(''now'') FROM product_registry"}, {"type": "sql", "name": "brief-products", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00Z'',''now''), ''product:'' || product, ''product'', product, CASE WHEN state <> ''active'' THEN ''paused'' WHEN rest_until > datetime(''now'') THEN ''resting'' WHEN last_plus_at IS NULL OR last_plus_at < datetime(''now'', ''-'' || (2*plus_cadence_h) || '' hours'') THEN ''stale'' ELSE ''ok'' END, CASE WHEN rest_until > datetime(''now'') THEN ''rest until '' || rest_until ELSE ''plus every '' || plus_cadence_h || ''h'' END, product || '': last plus '' || COALESCE(last_plus_at,''never'') || '', '' || misses_in_row || '' misses in a row, state '' || state FROM product_registry"}, {"type": "sql", "name": "brief-cost", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) WITH c AS (SELECT source_group, run_rate_30d_7d AS m FROM v_cost_run_rate WHERE source_group NOT LIKE ''total%''), t AS (SELECT COALESCE(SUM(m),0) AS total FROM c), top AS (SELECT source_group, m FROM c ORDER BY m DESC LIMIT 1) SELECT strftime(''%Y-%m-%dT%H:00Z'',''now''), ''manager:cost'', ''function'', ''cost'', CASE WHEN t.total > COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key=''cost_manager_monthly_usd''),100) THEN ''over'' ELSE ''ok'' END, ''cut the top source first'', ''Run rate about $'' || ROUND(t.total,0) || '' a month; top source '' || COALESCE(top.source_group,''none'') || '' at $'' || COALESCE(ROUND(top.m,0),0) || '' a month'' FROM t LEFT JOIN top"}, {"type": "sql", "name": "cost-issue", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) WITH c AS (SELECT source_group, run_rate_30d_7d AS m FROM v_cost_run_rate WHERE source_group NOT LIKE ''total%''), t AS (SELECT COALESCE(SUM(m),0) AS total FROM c), top AS (SELECT source_group, m FROM c ORDER BY m DESC LIMIT 1) SELECT ''COST-MANAGER-1: '' || top.source_group || '' is the biggest spend'', ''Run rate about $'' || ROUND(t.total,0) || '' a month against ceiling $'' || COALESCE((SELECT value FROM ops_config WHERE key=''cost_manager_monthly_usd''),''100'') || ''. Top source '' || top.source_group || '' at $'' || ROUND(top.m,0) || '' a month. Lever: move its callers to free Workers AI models, trim input tokens (shorter prompts, cached context, smaller retrieval), one leg instead of an ensemble. Read SELECT * FROM v_cost_run_rate ORDER BY run_rate_30d_7d DESC. Closes when the ledger total is under the ceiling.'', ''domain-managers'', ''cost'', ''high'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM t JOIN top WHERE t.total > COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key=''cost_manager_monthly_usd''),100) AND NOT EXISTS (SELECT 1 FROM agent_issues WHERE status=''open'' AND title LIKE ''COST-MANAGER-1:%'')"}, {"type": "sql", "name": "brief-social", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) WITH tg(channel, target) AS (VALUES (''bluesky'',21),(''linkedin'',7),(''mastodon'',14),(''x'',14)), s AS (SELECT tg.channel, tg.target, COALESCE(v.posts_7d,0) AS posts, COALESCE(v.clicks_per_post_7d,0) AS cpp FROM tg LEFT JOIN v_channel_impact_7d v ON v.channel = tg.channel) SELECT strftime(''%Y-%m-%dT%H:00Z'',''now''), ''manager:social'', ''function'', ''social'', CASE WHEN SUM(posts) < 0.5*SUM(target) THEN ''behind'' ELSE ''ok'' END, ''keep cadence; favour channels with more clicks per post'', group_concat(channel || '' '' || posts || ''/'' || target || '' ('' || cpp || '' clicks/post)'', ''; '') FROM s"}, {"type": "sql", "name": "social-issue", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) WITH tg(channel, target) AS (VALUES (''bluesky'',21),(''linkedin'',7),(''mastodon'',14),(''x'',14)), s AS (SELECT tg.channel, tg.target, COALESCE(v.posts_7d,0) AS posts, COALESCE(v.clicks_per_post_7d,0) AS cpp FROM tg LEFT JOIN v_channel_impact_7d v ON v.channel = tg.channel) SELECT ''SOCIAL-MANAGER-1: '' || channel || '' posted '' || posts || '' of '' || target || '' in 7 days'', ''Weekly cadence target '' || target || '', posted '' || posts || ''. Read v_channel_impact_7d and the qnfo-social queue for this channel (LinkedIn stays in draft mode; opt-out and ToS limits unchanged). Closes when posts_7d reaches half the target.'', ''domain-managers'', ''reach'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM s WHERE posts < 0.5*target AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status=''open'' AND a.title LIKE ''SOCIAL-MANAGER-1: '' || s.channel || '' %'')"}, {"type": "sql", "name": "brief-outreach", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00Z'',''now''), ''manager:outreach'', ''function'', ''outreach'', CASE WHEN SUM(sent_at >= datetime(''now'',''-7 days'') AND status IN (''sent'',''followup'')) = 0 THEN ''idle'' ELSE ''ok'' END, ''report only; consent and opt-out untouched'', ''sent or followed up in 7 days: '' || COALESCE(SUM(sent_at >= datetime(''now'',''-7 days'') AND status IN (''sent'',''followup'')),0) || '', failed in 7 days: '' || COALESCE(SUM(sent_at >= datetime(''now'',''-7 days'') AND status NOT IN (''sent'',''followup'')),0) FROM outreach_log"}, {"type": "sql", "name": "outreach-issue", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''OUTREACH-MANAGER-1: no outreach e-mail sent in 7 days'', ''outreach_log shows no sent or followup row in 7 days. Check the qnfo-outreach loop, its consented recipient list and the cron. Do not bypass suppression, opt-out or consent.'', ''domain-managers'', ''reach'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) WHERE NOT EXISTS (SELECT 1 FROM outreach_log WHERE sent_at >= datetime(''now'',''-7 days'') AND status IN (''sent'',''followup'')) AND NOT EXISTS (SELECT 1 FROM agent_issues WHERE status=''open'' AND title LIKE ''OUTREACH-MANAGER-1:%'')"}, {"type": "sql", "name": "actions", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, to_value, evidence) SELECT CASE WHEN title LIKE ''COST%'' THEN ''manager:cost'' WHEN title LIKE ''SOCIAL%'' THEN ''manager:social'' ELSE ''manager:outreach'' END, ''issue-filed'', id, title, ''domain-managers filed this from live D1 numbers'' FROM agent_issues WHERE source=''domain-managers'' AND created_at >= CAST(strftime(''%s'',''now'') AS INTEGER) - 120 AND NOT EXISTS (SELECT 1 FROM persona_actions p WHERE p.issue_id = agent_issues.id AND p.kind=''issue-filed'')"}, {"type": "sql", "name": "metric", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM persona_briefs WHERE tick = (SELECT MAX(tick) FROM persona_briefs WHERE persona_key=''manager:cost'') AND (persona_key LIKE ''manager:%'' OR persona_key LIKE ''product:%'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state=''MEASURED'' WHERE metric=''domain_manager_briefs''"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

